class Policy:
    # Track scores and prioritize unsolved tasks over solved ones within the current shard.
    def __init__(self):
        self.scores = {}  # task_id -> best score seen

    def pick(self, keys, round_index):
        # Filter to tasks we haven't seen solved (score < 1.0)
        unsolved = [k for k in keys if self.scores.get(k, 0.0) < 1.0]
        if unsolved:
            # Round-robin among unsolved tasks in the shard
            return unsolved[round_index % len(unsolved)]
        # All tasks in shard are solved or unknown; fall back to round-robin
        return keys[round_index % len(keys)]

    def record(self, task_id, score):
        # Keep the best score (solved status is sticky)
        if score > self.scores.get(task_id, 0.0):
            self.scores[task_id] = score
