class Policy:
    # Changed from pure round-robin to prioritize unsolved tasks first, then round-robin among remaining.
    # This avoids wasting rollouts on already-solved tasks (score >= 1.0) which yield no proposals.
    def __init__(self):
        self.scores = {}
        self.last_pick = {}

    def pick(self, keys, round_index):
        # Filter to unsolved tasks (score < 1.0 or never seen)
        unsolved = [k for k in keys if self.scores.get(k, 0) < 1.0]
        if not unsolved:
            unsolved = list(keys)  # all solved, just pick any

        # Among unsolved, prefer ones we haven't picked recently (round-robin within unsolved)
        # Use round_index to rotate through unsolved list
        return unsolved[round_index % len(unsolved)]

    def record(self, task_id, score):
        self.scores[task_id] = score
