Here's a revised policy that uses a hybrid approach: it prioritizes tasks with unknown scores (exploration) but also tracks and exploits known high-scoring tasks when they appear in the current shard, while avoiding solved tasks.

```python
class Policy:
    # Changed: prioritize unexplored tasks, then highest-scoring known tasks, avoiding solved ones.
    def __init__(self):
        self.scores = {}  # task_id -> best score seen
        self.attempts = {}  # task_id -> count of picks

    def pick(self, keys, round_index):
        # First, find tasks we've never tried
        untried = [k for k in keys if k not in self.scores]
        if untried:
            # Among untried, pick the one we've attempted least (round-robin-ish)
            return min(untried, key=lambda k: self.attempts.get(k, 0))

        # All tried: pick the highest-scoring unsolved task
        unsolved = [k for k in keys if self.scores.get(k, 0) < 1.0]
        if unsolved:
            return max(unsolved, key=lambda k: self.scores.get(k, 0))

        # All solved in shard — fall back to round-robin
        return keys[round_index % len(keys)]

    def record(self, task_id, score):
        # Keep best score per task
        if task_id not in self.scores or score > self.scores[task_id]:
            self.scores[task_id] = score
        self.attempts[task_id] = self.attempts.get(task_id, 0) + 1
